public enum Crop {
    MAIZE("Maize", 55), BEANS("Beans", 120), RICE("Rice", 140), SORGHUM("Sorghum", 45);

    private final String label;
    private final int pricePerKg;

    Crop(String label, int pricePerKg) {
        this.label = label;
        this.pricePerKg = pricePerKg;
    }

    public String getLabel() { return label; }
    public int getPricePerKg() { return pricePerKg; }

    public double value(double kg) {
        return kg * pricePerKg;
    }

    // valueOf throws IllegalArgumentException for names that aren't constants.
    public static Crop fromName(String name) {
        return Crop.valueOf(name.trim().toUpperCase());
    }

    public boolean isGrain() {
        return switch (this) {
            case MAIZE, RICE, SORGHUM -> true;
            case BEANS -> false;
        };
    }
}

