import java.util.List;

record Reading(String sensor, double litres, int hour) {
    Reading {
        if (sensor == null || sensor.isBlank()) throw new IllegalArgumentException("sensor name needed");
        if (litres < 0) throw new IllegalArgumentException("litres can't be negative");
        if (hour < 0 || hour > 23) throw new IllegalArgumentException("hour must be 0-23");
    }

    boolean isNight() { return hour < 6 || hour >= 20; }
}

public class Readings {
    public static double totalFor(List<Reading> rs, String sensor) {
        double total = 0;
        for (Reading r : rs) if (r.sensor().equals(sensor)) total += r.litres();
        return total;
    }

    public static int nightCount(List<Reading> rs) {
        int n = 0;
        for (Reading r : rs) if (r.isNight()) n++;
        return n;
    }
}

