import java.util.*;

// Checked: callers must plan for running out.
class OutOfStockException extends Exception {
    private final int wanted;
    private final int available;

    OutOfStockException(String item, int wanted, int available) {
        super("Only " + available + " " + item + " left, wanted " + wanted);
        this.wanted = wanted;
        this.available = available;
    }

    int getWanted() { return wanted; }
    int getAvailable() { return available; }
}

// Unchecked: a bad quantity is a programming mistake.
class InvalidQuantityException extends RuntimeException {
    InvalidQuantityException(int qty) {
        super("Quantity must be positive: " + qty);
    }
}

public class Pharmacy {
    private final Map<String, Integer> stock = new HashMap<>();

    public void addStock(String item, int qty) {
        if (qty <= 0) throw new InvalidQuantityException(qty);
        stock.put(item, stockOf(item) + qty);
    }

    public int stockOf(String item) {
        return stock.getOrDefault(item, 0);
    }

    public int dispense(String item, int qty) throws OutOfStockException {
        if (qty <= 0) throw new InvalidQuantityException(qty);
        int have = stockOf(item);
        if (qty > have) throw new OutOfStockException(item, qty, have);
        stock.put(item, have - qty);
        return have - qty;
    }

    public static String tryDispense(Pharmacy p, String item, int qty) {
        try {
            return "OK, " + p.dispense(item, qty) + " left";
        } catch (OutOfStockException e) {
            return e.getMessage();
        }
    }
}
